pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testRegression_property() public {
        address alice = address(0x1111);
        address bob = address(0x2222);
        vm.deal(alice, 20);
        vm.deal(bob, 20);

        vm.warp(1);
        vm.roll(2);
        vm.prank(alice);
        c.play{value: 10}();

        vm.warp(2);
        vm.roll(1);
        vm.prank(bob);
        c.play{value: 10}();

        assertTrue(c.pot() > 0);
    }
}
